// toolUIPermissions authorizes the isolated tool-UI hosts, whose requests are
// dispatched before the root router (tool_ui.go). They mirror the main-origin
// rows for the same tools.
var toolUIPermissions = map[string]Permission{
	"TOOLUI service":                {Resource: rbac.ResourceServices, Verb: rbac.VerbProxy},
	"TOOLUI cluster-grafana read":   {Resource: rbac.ResourceMonitoring, Verb: rbac.VerbRead, IDNamesCluster: true},
	"TOOLUI cluster-grafana update": {Resource: rbac.ResourceMonitoring, Verb: rbac.VerbUpdate, IDNamesCluster: true},
}
